/// 🧵️ Uses literal UTF8 boundaries through every original controlled owner text position.
fn hex_utf8_document_payload(hex:&str,slot:usize)->store::os_io::IoPayload{let body=match slot {0=>format!("schema={hex}\nruns=[]"),1=>format!("schema=73\nruns=[[{hex},63,[]]]"),2=>format!("schema=73\nruns=[[65,{hex},[]]]"),_=>format!("schema=73\nruns=[[65,63,[[l,{hex}]]]]")};store::os_io::IoPayload::Text(format!("semio s.stdio.semio.text.dsl v1\n{body}"))}
#[test]
fn sqlite_snapshot_semio_text_literal_hex_utf8_boundaries_and_nested_refusals(){
 let authority:serde_json::Value=serde_json::from_str(include_str!("../../../../../✉️base/🚪️io/🪶️sqlite/📸️snapshot/🧪️tests/🧫️fixtures/🧵️hex-utf8/🔣️.json")).unwrap();
 for case in authority["positive"].as_array().unwrap(){for slot in 0..4{let actual=SemioTextSnapshot::decode_sqlite_snapshot_native(&hex_utf8_document_payload(case["hex"].as_str().unwrap(),slot),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();assert_eq!(match slot {0=>actual.schema.as_str(),1=>actual.runs[0].language.as_str(),2=>actual.runs[0].content.as_str(),_=>actual.runs[0].marks[0].href.as_str()},case["text"].as_str().unwrap(),"{} slot={slot}",case["id"]);}}
 for case in authority["negative"].as_array().unwrap(){for slot in 0..4{assert!(SemioTextSnapshot::decode_sqlite_snapshot_native(&hex_utf8_document_payload(case["hex"].as_str().unwrap(),slot),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err(),"{} slot={slot}",case["id"]);}}eprintln!("[DEBUG] Semio Text original native routes checked literal UTF8 authority at 4 field positions");
}
